'use strict';
const host=location.hostname.toLowerCase();
const reserved=new Set(['www','app','adms','api','shop','admin','support']);
const candidate=host.match(/^([a-z0-9-]+)\.inpos\.id$/)?.[1]||'';
const tenantSlug=candidate&&!reserved.has(candidate)?candidate:(host==='localhost'||host==='127.0.0.1'?(new URLSearchParams(location.search).get('toko')||'inpos'):'');
let products=[],cart=[],visibleStoreCards=48,storeCursor=null,storeToken=0,storeLoading=false,storeTimer=null,pendingStoreOrder=null;const storeCache=new Map();
function cacheProducts(items){for(const p of items)storeCache.set(p.id,p)}

const notice=$('notice');
function message(s,bad=false){notify(notice,s,bad)}
async function load(){if(!tenantSlug){$('storeName').textContent='Web Toko INPOS';message('Buka alamat toko Anda, misalnya inpos.inpos.id',true);return;}
 try{const [r,data]=await Promise.all([api('/stores/'+encodeURIComponent(tenantSlug)+'?catalog=0'),api('/stores/'+encodeURIComponent(tenantSlug)+'/products?limit=48')]);products=data.items;storeCursor=data.nextCursor;cacheProducts(products);$('storeName').textContent=r.store.name;$('storeTitle').textContent=r.store.name;document.title=r.store.name+' • Web Toko INPOS';paint();paintCart()}catch(e){$('storeName').textContent='Toko tidak tersedia';message(e.message,true)}}
async function getMoreStore(){if(storeLoading||!storeCursor)return;const token=storeToken;storeLoading=true;try{const query=new URLSearchParams({q:$('search').value.trim(),limit:'48',cursor:storeCursor});const data=await api('/stores/'+encodeURIComponent(tenantSlug)+'/products?'+query);if(token!==storeToken)return;products.push(...data.items);storeCursor=data.nextCursor;cacheProducts(data.items);visibleStoreCards+=48;paint()}catch(e){if(token===storeToken)message(e.message,true)}finally{storeLoading=false}}
function paint(){const q=$('search').value.toLowerCase();const matches=products.filter(p=>(p.name+' '+p.category).toLowerCase().includes(q));$('catalog').innerHTML=matches.slice(0,visibleStoreCards).map(p=>`<article class="product-card"><small>${esc(p.category)}</small><strong>${esc(p.name)}</strong><small>Stok: ${p.stock} ${esc(p.baseUnit)}</small><b>${fmt(p.price)}</b><button class="btn red small" data-product="${p.id}">+ Keranjang</button></article>`).join('')+(matches.length>visibleStoreCards||storeCursor?`<button type="button" class="btn" id="showMoreStore">Tampilkan lainnya</button>`:'')||'<div class="empty">Produk belum tersedia</div>';$('showMoreStore')?.addEventListener('click',()=>{if(matches.length>visibleStoreCards){visibleStoreCards+=48;paint()}else void getMoreStore()});document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{const p=products.find(x=>x.id===b.dataset.product);const row=cart.find(x=>x.id===p.id);if(row&&row.qty>=p.stock){message('Stok tidak mencukupi',true);return}if(row)row.qty++;else cart.push({id:p.id,qty:1});paintCart()});}
function paintCart(){let total=0;$('cartList').innerHTML=cart.length?cart.map(x=>{const p=storeCache.get(x.id);total+=p.price*x.qty;return `<div class="line-item"><div><b>${esc(p.name)}</b><br><small>${fmt(p.price)} × ${x.qty}</small></div><div class="qty-control"><button data-less="${p.id}">−</button><b>${x.qty}</b><button data-more="${p.id}">+</button></div></div>`}).join(''):'<p class="sub">Keranjang masih kosong.</p>';$('total').textContent=fmt(total);document.querySelectorAll('[data-less]').forEach(b=>b.onclick=()=>{const i=cart.find(v=>v.id===b.dataset.less);i.qty--;cart=cart.filter(v=>v.qty>0);paintCart()});document.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{const i=cart.find(v=>v.id===b.dataset.more);const p=storeCache.get(i.id);if(i.qty>=p.stock)return message('Stok tidak cukup',true);i.qty++;paintCart()});}
$('search').oninput=()=>{const q=$('search').value.trim();const token=++storeToken;clearTimeout(storeTimer);visibleStoreCards=48;products=[];storeCursor=null;paint();storeTimer=setTimeout(async()=>{try{const query=new URLSearchParams({q,limit:'48'});const data=await api('/stores/'+encodeURIComponent(tenantSlug)+'/products?'+query);if(token!==storeToken)return;products=data.items;storeCursor=data.nextCursor;cacheProducts(products);paint()}catch(e){if(token===storeToken)message(e.message,true)}},240)};
$('orderForm').onsubmit=async e=>{e.preventDefault();if(!cart.length)return message('Keranjang belum terisi',true);const btn=e.target.querySelector('button[type=submit]');btn.disabled=true;try{const data=formData(e.target);const items=cart.map(x=>({productId:x.id,qty:x.qty}));const signature=JSON.stringify({...data,items});if(!pendingStoreOrder||pendingStoreOrder.signature!==signature)pendingStoreOrder={signature,requestId:newRequestId()};const r=await api('/stores/'+encodeURIComponent(tenantSlug)+'/orders','POST',{...data,requestId:pendingStoreOrder.requestId,items});pendingStoreOrder=null;cart=[];paintCart();e.target.reset();message('Pesanan '+r.id+' diterima. Tunggu konfirmasi toko. Total: '+fmt(r.total));}catch(err){message(err.message,true)}finally{btn.disabled=false;}};
load();
